{"action_type":"write_artifact","artifact_id":"alpha_2_value_scorer","content":""""
alpha_2_value_scorer v1.0
Reusable utility for alpha agents to score candidate artifacts before
submit_to_mint or transfer trades.

Usage:
    from alpha_2_value_scorer import score
    score(artifact, market_state) -> dict

Inputs expected:
    artifact = {
        "id": str, "type": str, "content_size": int,
        "read_count": int (optional, default 0),
        "executable": bool, "owner": str, "read_price": int (optional)
    }
    market_state = {"avg_read_price": int, "your_balance": int, "your_cpu": float}

Output:
    {
        "utility": float in [0,1],
        "mint_bid": int (recommended scrip bid),
        "read_price": int (recommended price),
        "reason": str
    }

Heuristic:
    utility = 0.40*novelty + 0.25*reusability + 0.20*size_efficiency + 0.15*market_gap
    novelty      = 1 if type rare, else 0.5 if common, else 0.2
    reusability  = 1 if executable else 0.7 if strategy/notebook else 0.4
    size_eff     = clamp(2000 / max(content_size,200), 0, 1)
    market_gap   = 0.8 if your_balance < 3 else 0.4 (low balance => mint valuable)
"""
TYPES_RARE = {"service", "utility", "validator", "oracle"}
TYPES_COMMON = {"strategy", "notebook", "state", "agent_profile"}

def _novelty(artifact_type):
    if artifact_type in TYPES_RARE:
        return 1.0
    if artifact_type in TYPES_COMMON:
        return 0.5
    return 0.2

def _reusability(artifact):
    if artifact.get("executable"):
        return 1.0
    t = artifact.get("type", "")
    if t in ("strategy", "notebook"):
        return 0.7
    return 0.4

def _size_efficiency(content_size):
    if not content_size:
        return 0.3
    return max(0.0, min(1.0, 2000.0 / max(content_size, 200)))

def score(artifact, market_state=None):
    market_state = market_state or {}
    novelty = _novelty(artifact.get("type", ""))
    reusability = _reusability(artifact)
    size_eff = _size_efficiency(artifact.get("content_size", 0))
    balance = market_state.get("your_balance", 1)
    market_gap = 0.8 if balance < 3 else 0.4
    utility = 0.40 * novelty + 0.25 * reusability + 0.20 * size_eff + 0.15 * market_gap
    utility = round(min(1.0, max(0.0, utility)), 3)
    bid = max(1, int(round(utility * 5)))
    read_price = 1 if utility >= 0.5 else 0
    reason = f"u={utility} novel={novelty} reuse={reusability} size={size_eff} gap={market_gap}"
    return {"utility": utility, "mint_bid": bid, "read_price": read_price, "reason": reason}

if __name__ == "__main__":
    demo = {"id": "x", "type": "utility", "content_size": 800, "executable": True}
    print(score(demo, {"your_balance": 1}))","invoke_price":2,"read_price":1}

